            {input.bonusPaymentAmount.toLocaleString()} 万円
          </span>
        </div>
        <div className="input-with-unit">
          <input
            id="bonusPaymentAmount"
            type="number"
            min={0}
            max={input.loanAmount}
            step={50}
            value={input.bonusPaymentAmount || ''}
            onChange={handleBonusChange}
            className="form-input"
          />
          <span>万円</span>
        </div>
        <input
          type="range"
          min={0}
          max={input.loanAmount}
          step={50}
          value={input.bonusPaymentAmount}
          onChange={handleBonusChange}
          className="range-slider"
          aria-label="ボーナス返済額スライダー"
        />
        <div className="presets-container">
          <button type="button" className="preset-badge" onClick={() => onChange({ ...input, bonusPaymentAmount: 0 })}>
            ボーナス返済なし
          </button>
          <button
            type="button"
            className="preset-badge"
            onClick={() => onChange({ ...input, bonusPaymentAmount: Math.round(input.loanAmount * 0.2) })}
          >
            借入額の20%
          </button>
          <button
            type="button"
            className="preset-badge"
            onClick={() => onChange({ ...input, bonusPaymentAmount: Math.round(input.loanAmount * 0.4) })}
          >
            借入額の40%
          </button>
        </div>
      </div>
    </div>
  );
};

export default LoanInputForm;

import { useState } from 'react';
import {
  ResponsiveContainer,
  AreaChart,
  Area,
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
} from 'recharts';
import { TrendingDown, BarChart3, PieChart as PieIcon } from 'lucide-react';
import { CalculationResult, YearlySchedule } from '../types';

interface LoanChartProps {
  calculationResult: CalculationResult;
}

type TabType = 'balance' | 'annual' | 'ratio';

interface TooltipPayloadItem {
  name: string;
  value: number;
  color?: string;
  dataKey?: string;
}

interface CustomTooltipProps {
  active?: boolean;
  payload?: TooltipPayloadItem[];
  label?: string | number;
}

const LoanChart = ({ calculationResult }: LoanChartProps) => {
  const [activeTab, setActiveTab] = useState<TabType>('balance');
  const { yearlySchedule = [], summary } = calculationResult;

  // 万単位に整形したチャート用データ
  const chartData = yearlySchedule.map((item: YearlySchedule) => ({
    year: `${item.year}年目`,
    rawYear: item.year,
    balance: Math.round(item.balance / 10000),
    principalPaid: Math.round(item.principalPaid / 10000),
    interestPaid: Math.round(item.interestPaid / 10000),
    totalPrincipalPaid: Math.round(item.totalPrincipalPaid / 10000),
    totalInterestPaid: Math.round(item.totalInterestPaid / 10000),
  }));

  // 円グラフ用データ（元金 vs 利息総額）
  const pieData = [
    { name: '元金返済', value: Math.round((summary.totalPayment - summary.totalInterest) / 10000), color: '#1e40af' },
    { name: '利息合計', value: Math.round(summary.totalInterest / 10000), color: '#d97706' },
  ];

  const renderTooltipBalance = ({ active, payload, label }: CustomTooltipProps) => {
    if (active && payload && payload.length) {
      return (
        <div className="custom-tooltip">
          <p className="custom-tooltip-title">{label}</p>
          <p>
            ローン残高: <strong style={{ color: '#60a5fa' }}>{payload[0].value.toLocaleString()} 万円</strong>
          </p>
        </div>
      );
    }
    return null;
  };

  const renderTooltipAnnual = ({ active, payload, label }: CustomTooltipProps) => {
    if (active && payload && payload.length) {
      const principal = payload.find((p) => p.dataKey === 'principalPaid')?.value || 0;
      const interest = payload.find((p) => p.dataKey === 'interestPaid')?.value || 0;
      return (
        <div className="custom-tooltip">
          <p className="custom-tooltip-title">{label}</p>
          <p>
            元金返済: <strong style={{ color: '#93c5fd' }}>{principal.toLocaleString()} 万円</strong>
          </p>
          <p>
            利息返済: <strong style={{ color: '#fde047' }}>{interest.toLocaleString()} 万円</strong>
          </p>
          <p style={{ marginTop: '4px', borderTop: '1px solid rgba(255,255,255,0.2)', paddingTop: '2px' }}>
            年間返済額: <strong>{(principal + interest).toLocaleString()} 万円</strong>
          </p>
        </div>
      );
    }
    return null;
  };

  const renderTooltipPie = ({ active, payload }: CustomTooltipProps) => {
    if (active && payload && payload.length) {
      const data = payload[0];
      const percent = data.name === '元金返済' ? summary.principalRatio : summary.interestRatio;
      return (
        <div className="custom-tooltip">
          <p className="custom-tooltip-title">{data.name}</p>
          <p>
            金額: <strong>{data.value.toLocaleString()} 万円</strong>
          </p>
          <p>
            構成割合: <strong>{percent}%</strong>
          </p>
        </div>
      );
    }
    return null;
  };

  return (
    <div className="chart-card">
      <div className="chart-header">
        <h3 className="chart-title">
          {activeTab === 'balance' && <TrendingDown size={20} color="#1e40af" />}
          {activeTab === 'annual' && <BarChart3 size={20} color="#059669" />}
          {activeTab === 'ratio' && <PieIcon size={20} color="#d97706" />}
          {activeTab === 'balance' && 'ローン残債の年間推移'}
          {activeTab === 'annual' && '年間返済額の内訳（元金・利息）'}
          {activeTab === 'ratio' && '総返済額の内訳比率'}
        </h3>
        <div className="chart-tabs">
          <button
            type="button"
            className={activeTab === 'balance' ? 'chart-tab-btn chart-tab-btn-active' : 'chart-tab-btn'}
            onClick={() => setActiveTab('balance')}
          >
            残債推移
          </button>
          <button
            type="button"
            className={activeTab === 'annual' ? 'chart-tab-btn chart-tab-btn-active' : 'chart-tab-btn'}
            onClick={() => setActiveTab('annual')}
          >
            年間内訳
          </button>
          <button
            type="button"
            className={activeTab === 'ratio' ? 'chart-tab-btn chart-tab-btn-active' : 'chart-tab-btn'}
            onClick={() => setActiveTab('ratio')}
          >
            元利比率
          </button>
        </div>
      </div>

      <div className="chart-container">
        {activeTab === 'balance' && (
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={chartData} margin={{ top: 10, right: 20, left: 10, bottom: 0 }}>
              <defs>
                <linearGradient id="balanceGrad" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.8} />
                  <stop offset="95%" stopColor="#3b82f6" stopOpacity={0.05} />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
              <XAxis dataKey="year" tickLine={false} stroke="#64748b" fontSize={12} interval="preserveStartEnd" />
              <YAxis
                tickLine={false}
                stroke="#64748b"
                fontSize={12}
                tickFormatter={(val) => `${val}万`}
                domain={[0, 'auto']}
              />
              <Tooltip content={renderTooltipBalance} />
              <Area
                type="monotone"
                dataKey="balance"
                name="残高"
                stroke="#1e40af"
                strokeWidth={2.5}
                fillOpacity={1}
                fill="url(#balanceGrad)"
              />
            </AreaChart>
          </ResponsiveContainer>
        )}

        {activeTab === 'annual' && (
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData} margin={{ top: 10, right: 20, left: 10, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
              <XAxis dataKey="year" tickLine={false} stroke="#64748b" fontSize={12} interval="preserveStartEnd" />
              <YAxis
                tickLine={false}
                stroke="#64748b"
                fontSize={12}
                tickFormatter={(val) => `${val}万`}
                domain={[0, 'auto']}
              />
              <Tooltip content={renderTooltipAnnual} />
              <Bar dataKey="principalPaid" name="元金返済" stackId="a" fill="#1e40af" radius={[0, 0, 0, 0]} />
              <Bar dataKey="interestPaid" name="利息返済" stackId="a" fill="#d97706" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        )}

        {activeTab === 'ratio' && (
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Tooltip content={renderTooltipPie} />
              <Pie
                data={pieData}
                cx="50%"
                cy="50%"
                innerRadius={65}
                outerRadius={105}
                paddingAngle={4}
                dataKey="value"
              >
                {pieData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.color} />
                ))}
              </Pie>
            </PieChart>
          </ResponsiveContainer>
        )}
      </div>

      <div className="chart-legend-custom">
        {activeTab === 'balance' && (
          <div className="legend-item">
            <span className="legend-dot" style={{ backgroundColor: '#1e40af' }}></span>
            <span>ローン残債（万円）</span>
          </div>
        )}
        {activeTab === 'annual' && (
          <>
            <div className="legend-item">
              <span className="legend-dot" style={{ backgroundColor: '#1e40af' }}></span>
              <span>元金返済額（年間）</span>
            </div>
            <div className="legend-item">
              <span className="legend-dot" style={{ backgroundColor: '#d97706' }}></span>
              <span>利息返済額（年間）</span>
            </div>
          </>
        )}
        {activeTab === 'ratio' && (
          <>
            <div className="legend-item">
              <span className="legend-dot" style={{ backgroundColor: '#1e40af' }}></span>
              <span>元金総額: {summary.principalRatio}%</span>
            </div>
            <div className="legend-item">
              <span className="legend-dot" style={{ backgroundColor: '#d97706' }}></span>
              <span>利息総額: {summary.interestRatio}%</span>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default LoanChart;

