                <Calendar size={20} color="#1e40af" /> 年間返済推移表（償還表）
              </h3>
            </div>
            <div className="schedule-table-wrapper">
              <table className="schedule-table">
                <thead>
                  <tr className="table-header">
                    <th style={{ textAlign: 'center' }}>年数</th>
                    <th>年間返済額</th>
                    <th>うち年間元金</th>
                    <th>うち年間利息</th>
                    <th>年末ローン残高</th>
                    <th>累計支払利息</th>
                  </tr>
                </thead>
                <tbody>
                  {yearlySchedule.map((item) => {
                    const annualPayment = item.principalPaid + item.interestPaid;
                    return (
                      <tr key={item.year} className="table-row">
                        <td className="table-cell" style={{ textAlign: 'center', fontWeight: 600 }}>
                          {item.year} 年目
                        </td>
                        <td className="table-cell table-number">
                          <strong>{formatCurrency(annualPayment)}</strong> 円
                        </td>
                        <td className="table-cell table-number">{formatCurrency(item.principalPaid)} 円</td>
                        <td className="table-cell table-number" style={{ color: '#d97706' }}>
                          {formatCurrency(item.interestPaid)} 円
                        </td>
                        <td className="table-cell table-number" style={{ fontWeight: 600 }}>
                          {formatCurrency(item.balance)} 円
                        </td>
                        <td className="table-cell table-number" style={{ color: 'var(--color-text-muted)' }}>
                          {formatCurrency(item.totalInterestPaid)} 円
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </section>
        </main>
      </div>
    </div>
  );
};

export default App;
